Source code in <code>XML\xml_core_types.py</code> <pre><code>def _validate_xml_schema() -&gt; None:
    used: set[PersonFields] = set()
    for op in ERZLCreatePersonOp:
        required = op.value.required
        optional = op.value.optional

        if len(required) != len(set(required)):
            raise RuntimeError(
                f"В {op.name}.required есть повторяющиеся поля: {required}"
            )

        if len(optional) != len(set(optional)):
            raise RuntimeError(
                f"В {op.name}.optional есть повторяющиеся поля: {optional}"
            )

        overlap = set(required) &amp; set(optional)
        if overlap:
            raise RuntimeError(
                f"В {op.name} поля одновременно находятся в required и optional: {overlap}"
            )

        used.update(op.value.allKeys)

    missing = used - set(XML_FIELDS_RENAME.keys())
    if missing:
        raise RuntimeError(f"Нет XML_FIELDS_RENAME для полей: {missing}")
